"""Apply Ronan Drive source changes against the pinned Fermata revision. GPL-3.0."""
from pathlib import Path
import base64, gzip, subprocess, sys
root = Path(sys.argv[1]).resolve()
patch = gzip.decompress(base64.b64decode(''))
subprocess.run(['git','apply','--check','-'], input=patch, cwd=root, check=True)
subprocess.run(['git','apply','-'], input=patch, cwd=root, check=True)
(root / 'RONAN-CHANGES.patch').write_bytes(patch)
print('Ronan Drive adaptive fit, branding and privacy changes applied')
